{"command": "cd /workspace && cat > work/gen.py << 'EOF'
import numpy as np, base64, os, json, sys

SR = 33452  # 4 * 8363

def b64(pcm_bytes):
    return base64.b64encode(pcm_bytes).decode()

def to_pcm16(x):
    x = np.clip(x, -1, 1)
    return (x * 32767.0).astype('<i2').tobytes()

def write_raw(path, x):
    with open(path,'wb') as f:
        f.write(to_pcm16(x))

def sine(f, dur, sr=SR, amp=0.8, phase=0.0):
    t = np.arange(int(dur*sr))/sr
    return amp*np.sin(2*np.pi*f*t + phase)

if __name__ == '__main__':
    x = sine(440, 1.0, amp=0.9)
    # fade in/out small
    write_raw('work/sine440.raw', x)
    print('ok', len(x))
EOF
python3 work/gen.py && ls -la work/"}

