import sys; sys.path.insert(0,'/workspace/work')
from eval import evaluate
import numpy as np
SR=33452
def pw(f,dur,duty,amp=0.6):
    t=np.arange(int(dur*SR))/SR
    return amp*np.where((f*t)%1<duty,1.0,-1.0)
def sw(f,dur,amp=0.6):
    t=np.arange(int(dur*SR))/SR
    return amp*np.sin(2*np.pi*f*t)
def tri(f,dur,amp=0.6):
    t=np.arange(int(dur*SR))/SR
    ph=(f*t)%1
    return amp*(4*np.abs(ph-0.5)-1)
def qsine(f,dur,nl,amp=0.6):
    x=np.sin(2*np.pi*f*np.arange(int(dur*SR))/SR)
    return amp*np.round(x*(nl//2))/(nl//2)
tests={
 'sine440':sw(440,0.12),
 'sine220':sw(220,0.12),
 'tri440':tri(440,0.12),
 'q4_440':qsine(440,0.12,4),
 'q8_440':qsine(440,0.12,8),
